___CSS_LOADER_EXPORT___.push([module.id, `.query-editor-enhanced__overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
}

.query-editor-enhanced__modal {
  width: min(1200px, calc(100vw - 48px));
  height: min(760px, calc(100vh - 48px));
  background: #1e1e1e;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.query-editor-enhanced__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.query-editor-enhanced__header h3 {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
}

.query-editor-enhanced__close {
  border: none;
  background: transparent;
  color: rgba(255, 255, 255, 0.75);
  cursor: pointer;
  font-size: 16px;
  padding: 4px 8px;
}

.query-editor-enhanced__close:hover {
  color: rgba(255, 255, 255, 0.95);
}

.query-editor-enhanced__body {
  flex: 1;
  min-height: 0;
}

.query-editor-enhanced__split {
  height: 100%;
  display: flex;
}

.query-editor-enhanced__left {
  flex: 1;
  min-width: 0;
}

.query-editor-enhanced__editor {
  height: 100%;
}

.query-editor-enhanced__divider {
  width: 6px;
  cursor: col-resize;
  background: rgba(255, 255, 255, 0.06);
}

.query-editor-enhanced__divider:hover {
  background: rgba(255, 255, 255, 0.12);
}

.query-editor-enhanced__right {
  border-left: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(255, 255, 255, 0.03);
  overflow: auto;
}

.query-editor-enhanced__right-empty {
  padding: 10px 12px;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.7);
}

.query-editor-enhanced__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 12px;
  border-top: 1px solid rgba(255, 255, 255, 0.12);
}

.query-editor-enhanced__hint {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.65);
}

.query-editor-enhanced__actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.query-editor-enhanced__btn {
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 6px;
  padding: 6px 10px;
  cursor: pointer;
}

.query-editor-enhanced__btn--secondary {
  background: transparent;
  color: rgba(255, 255, 255, 0.85);
}

.query-editor-enhanced__btn--secondary:hover {
  background: rgba(255, 255, 255, 0.06);
}

.query-editor-enhanced__btn--primary {
  background: #0e639c;
  color: white;
  border-color: rgba(14, 99, 156, 0.8);
}

.query-editor-enhanced__btn--primary:hover {
  background: #1177bb;
}


/* Monaco suggest-widget: иногда в webview отображаются только иконки без текста.
   Принудительно задаём цвета/размеры для текста подсказок. */
.query-editor-enhanced__modal .monaco-editor .suggest-widget .monaco-icon-label .label-name,
.query-editor-enhanced__modal .monaco-editor .suggest-widget .monaco-icon-label .label-description {
  color: rgba(255, 255, 255, 0.92) !important;
  font-size: 12px !important;
  opacity: 1 !important;
}

.query-editor-enhanced__modal .monaco-editor .suggest-widget .monaco-list-row:hover .monaco-icon-label .label-name {
  color: rgba(255, 255, 255, 0.98) !important;
}

.query-editor-enhanced__modal .monaco-editor .suggest-widget {
  background: #252526 !important;
}
